insert into fx select 'otherpet',id from save_patient(null,(select id from fx where k='client'),null,'Other Patient','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) values('e5100000-0000-4000-8000-000000000001','https://api.trial.ezyvet.com','weight-site','animal','77','{"id":77,"contact_id":8}','animal-hash','e5000000-0000-4000-8000-000000000001');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by) values('e5200000-0000-4000-8000-000000000001',gen_random_uuid(),'mapping-hash','https://api.trial.ezyvet.com','weight-site','animal','77','e5100000-0000-4000-8000-000000000001',1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','Fixture reviewed mapping','e5000000-0000-4000-8000-000000000001');
set local role service_role;
select throws_ok($$select claim_ezyvet_import(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001','weight-site','healthstatus','https://api.trial.ezyvet.com')$$,'23514',null,'Generic import cannot bypass required patient mapping');
select throws_ok($$select claim_ezyvet_import(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001','weight-site','diagnostic','https://api.trial.ezyvet.com')$$,'23514',null,'Misleading diagnostic list run disabled');
select throws_ok($$select claim_ezyvet_weight_import(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001','other-site','https://api.trial.ezyvet.com','e5200000-0000-4000-8000-000000000001')$$,'42501',null,'Source-site mismatch denied');
insert into rr select claim_ezyvet_weight_import('e5300000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001','weight-site','https://api.trial.ezyvet.com','e5200000-0000-4000-8000-000000000001');
select is((select v->>'animal_external_id' from rr),'77','Patient filter derived from reviewed mapping');
select throws_ok($$select stage_ezyvet_import_page('e5300000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from rr),1,true,'[{"external_id":"9","payload":{"id":9,"animal_id":999}}]')$$,'23514',null,'Wrong-patient provider result rejected');
select stage_ezyvet_import_page('e5300000-0000-4000-8000-000000000001','e5000000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from rr),1,true,'[{"external_id":"9","payload":{"id":9,"animal_id":77,"active":"true","weight":"12.3","weight_unit":"kg","timestamp":"1788267600"}},{"external_id":"10","payload":{"id":10,"animal_id":77,"active":true,"weight":"15","weight_unit":"kg","timestamp":"1788267600"}}]');
insert into fx select 'source',id from ezyvet_import_snapshots where resource='healthstatus' and external_id='9' and source_site_uid='weight-site';
insert into fx select 'source2',id from ezyvet_import_snapshots where resource='healthstatus' and external_id='10' and source_site_uid='weight-site';
select throws_ok($$select approve_ezyvet_weight(gen_random_uuid(),'e5000000-0000-4000-8000-000000000001',(select id from fx where k='source'),'hash',1,'e5200000-0000-4000-8000-000000000001',1,'create',null,12.3,'kg','2026-09-01',true,'Reviewed historical weight')$$,'42501',null,'Service cannot approve chart changes');
reset role;
create function pg_temp.approve_weight(request uuid,source uuid,weight numeric default 12.3,unit text default 'kg',measured date default '2026-09-01',target uuid default null) returns uuid language plpgsql as $$
declare s public.ezyvet_import_snapshots;payload jsonb;a public.ezyvet_weight_approvals;begin
 select * into strict s from ezyvet_import_snapshots where id=source;
 payload:=jsonb_build_object('snapshot_id',source,'expected_hash',s.payload_hash,'head_version',1,'animal_link_id','e5200000-0000-4000-8000-000000000001','patient_version',1,'action',case when target is null then 'create' else 'link' end,'weight_id',target,'weight',weight,'unit',unit,'measured_at',measured,'reason','Reviewed historical measurement');
 perform prepare_ezyvet_weight_request(request,source,payload);
 a:=approve_ezyvet_weight(request,auth.uid(),source,s.payload_hash,1,'e5200000-0000-4000-8000-000000000001',1,case when target is null then 'create' else 'link' end,target,weight,unit,measured,true,'Reviewed historical measurement');return a.weight_id;
end $$;
insert into ezyvet_identity_heads(source_origin,source_site_uid,resource,external_id,snapshot_id,version) values('https://api.trial.ezyvet.com','weight-site','animal','77','e5100000-0000-4000-8000-000000000001',1);
insert into fx select k,gen_random_uuid() from unnest(array['migration','scope','binding']) k;
create temp table evidence(k text primary key,v jsonb);grant all on evidence to authenticated;
set local role authenticated;
select prepare_ezyvet_migration_run((select id from fx where k='migration'),'https://api.trial.ezyvet.com','weight-site',jsonb_build_array(jsonb_build_object('id',(select id from fx where k='scope'),'mapping_id','e5200000-0000-4000-8000-000000000001','resource','healthstatus','parent_type','animal','parent_snapshot_id','e5100000-0000-4000-8000-000000000001','parent_head_version',1,'disposition','required','reason','Synthetic weight scope')));
select bind_ezyvet_migration_child((select id from fx where k='binding'),(select id from fx where k='scope'),'e5300000-0000-4000-8000-000000000001','Synthetic weight observations');
insert into evidence select i->>'external_id',i from jsonb_array_elements(list_ezyvet_migration_items((select id from fx where k='binding'))->'items') i;
create function pg_temp.receipt(item text default '9',bef timestamptz default null,bid uuid default null,lim integer default 20) returns jsonb language sql as $$select list_ezyvet_migration_weight_evidence((select id from fx where k='binding'),(v->>'page')::integer,(v->>'snapshot_id')::uuid,v->>'evidence_hash',bef,bid,lim) from evidence where k=item;$$;
select is(pg_temp.receipt()->'approval','null'::jsonb,'Staging does not imply approval');
insert into fx select 'weight',pg_temp.approve_weight('e5400000-0000-4000-8000-000000000001',(select id from fx where k='source'));
select is(pg_temp.receipt()#>>'{approval,action}','create','Creation receipt');
select is(pg_temp.receipt()#>>'{approval,relationship}','exact_snapshot','Exact snapshot recognized');
select is(pg_temp.receipt()#>>'{approval,source_current}','true','Approval head currently matches');
select is(pg_temp.receipt()#>>'{approval,local_weight_matches}','true','Native values match reviewed values');
select is(pg_temp.receipt()#>>'{approval,household_current}','true','Household matches saved mapping');
select is(pg_temp.receipt()->>'historical_head_fidelity','unknown','Historical observation head remains unknown');
select is(pg_temp.receipt()->'observation_head_version','null'::jsonb,'No invented observation head');
select is(pg_temp.receipt()->>'complete_coverage_verified','false','No coverage inferred');
select pg_temp.approve_weight('e5400000-0000-4000-8000-000000000002',(select id from fx where k='source2'),12.3,'kg','2026-09-01',(select id from fx where k='weight'));
select is(pg_temp.receipt('10')#>>'{approval,action}','link','Link remains distinct from creation');
select is(pg_temp.receipt('10')#>>'{approval,weight_id}',(select id::text from fx where k='weight'),'Link keeps original native weight');
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) values('e5500000-0000-4000-8000-000000000001','https://api.trial.ezyvet.com','weight-site','healthstatus','9','{"id":9,"animal_id":77,"active":true,"weight":"12.9","weight_unit":"kg"}','corrected-source-hash','e5000000-0000-4000-8000-000000000001');
insert into ezyvet_import_pages(run_id,page,item_count) values('e5300000-0000-4000-8000-000000000001',2,1);
insert into ezyvet_import_page_items(run_id,page,snapshot_id) values('e5300000-0000-4000-8000-000000000001',2,'e5500000-0000-4000-8000-000000000001');
set local role authenticated;
insert into evidence select 'changed',i from jsonb_array_elements(list_ezyvet_migration_items((select id from fx where k='binding'))->'items') i where i->>'page'='2';
select is(pg_temp.receipt()#>>'{approval,source_current}','false','Source drift does not rewrite approval');
select is(pg_temp.receipt('changed')#>>'{approval,relationship}','different_snapshot','Changed page retains separate approval snapshot');
select review_ezyvet_weight_change('e5600000-0000-4000-8000-000000000001','e5400000-0000-4000-8000-000000000001','e5500000-0000-4000-8000-000000000001',2,'Reviewed discrepancy without replacing chart');
select review_ezyvet_weight_change('e5600000-0000-4000-8000-000000000002','e5400000-0000-4000-8000-000000000001','e5500000-0000-4000-8000-000000000001',2,'Reviewed discrepancy without replacing chart');
select is(pg_temp.receipt()#>>'{reviews,0,relationship}','different_snapshot','Acknowledgment is distinct from original page');
select is(pg_temp.receipt('changed')#>>'{reviews,0,relationship}','exact_snapshot','Changed page matches acknowledgment snapshot');
select is(pg_temp.receipt()#>>'{reviews,0,source_current}','true','Acknowledged version is current');
insert into evidence values('first',pg_temp.receipt('9',null,null,1));
select is((select v->>'has_more' from evidence where k='first'),'true','Reviews independently paginate');
select is((select v#>>'{next_cursor,before_id}' from evidence where k='first'),'e5600000-0000-4000-8000-000000000002','Tied timestamps use UUID cursor');
insert into evidence select 'second',pg_temp.receipt('9',(v#>>'{next_cursor,before_at}')::timestamptz,(v#>>'{next_cursor,before_id}')::uuid,1) from evidence where k='first';
select is((select v#>>'{reviews,0,id}' from evidence where k='second'),'e5600000-0000-4000-8000-000000000001','Second review recovered exactly once');
select is((select v->>'has_more' from evidence where k='second'),'false','Review pagination terminates');
select is((select v->'approval' from evidence where k='first'),(select v->'approval' from evidence where k='second'),'Review cursor never hides approval');
reset role;
update ezyvet_identity_heads set snapshot_id=(select id from fx where k='source'),version=3 where resource='healthstatus' and external_id='9' and source_site_uid='weight-site';
set local role authenticated;
select is(pg_temp.receipt()#>>'{approval,relationship}','exact_snapshot','A to B to A preserves snapshot relation');
select is(pg_temp.receipt()#>>'{approval,source_current}','false','A to B to A does not revive original approval head');
select is(pg_temp.receipt()->>'historical_head_fidelity','unknown','A to B to A cannot reconstruct observation version');
select is(pg_temp.receipt()#>>'{reviews,0,source_current}','false','Old discrepancy acknowledgment is stale after source return');
