select throws_ok($$select list_ezyvet_migration_weight_evidence((select id from fx where k='binding'),3,(v->>'snapshot_id')::uuid,v->>'evidence_hash') from evidence where k='9'$$,'42501','Exact owned weight observation required','Wrong page denied');
select throws_ok($$select list_ezyvet_migration_weight_evidence(gen_random_uuid(),1,(v->>'snapshot_id')::uuid,v->>'evidence_hash') from evidence where k='9'$$,'42501','Exact owned weight observation required','Wrong binding denied');
select throws_ok($$select pg_temp.receipt('9',now(),null)$$,'23514','Invalid weight evidence identity or cursor','Partial cursor denied');
