-- Model preexisting drift in rollback-only superuser fixture; restore the live write guard before reads.
alter table pets disable trigger pets_version;
update pets set client_id=(select id from fx where k='movedhousehold') where id=(select id from fx where k='pet');
alter table pets enable trigger pets_version;
select is((select tgenabled::text from pg_trigger where tgrelid='public.pets'::regclass and tgname='pets_version'),'O','Ownership write guard restored before receipt reads');
set local role authenticated;
select is(pg_temp.receipt()#>>'{approval,household_current}','false','Changed household remains visible as drift');
select is(pg_temp.receipt()#>>'{approval,id}','e5400000-0000-4000-8000-000000000001','Changed household preserves historical receipt');
select is(jsonb_array_length(pg_temp.receipt()->'reviews'),2,'Changed household preserves acknowledgments');
select throws_ok($$select list_ezyvet_migration_weight_evidence((select id from fx where k='binding'),1,(select id from fx where k='source2'),(select v->>'evidence_hash' from evidence where k='9'))$$,'42501','Exact owned weight observation required','Other source snapshot cannot borrow observation hash');
select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select pg_temp.receipt()$$,'42501','Exact owned weight observation required','Other administrator denied');
reset role;
delete from user_roles where user_id='e5000000-0000-4000-8000-000000000002' and role='ADMIN';
set local role authenticated;
select throws_ok($$select pg_temp.receipt()$$,'42501','Active administrator required','Active non-administrator denied');
reset role;
select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
update profiles set is_active=false where id='e5000000-0000-4000-8000-000000000001';
set local role authenticated;select set_config('request.jwt.claims','{"sub":"e5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select pg_temp.receipt()$$,'42501','Active administrator required','Revoked administrator denied');
reset role;
select ok(not has_function_privilege('anon','public.list_ezyvet_migration_weight_evidence(uuid,integer,uuid,text,timestamptz,uuid,integer)','execute'),'Anonymous denied');
select ok(not has_function_privilege('service_role','public.list_ezyvet_migration_weight_evidence(uuid,integer,uuid,text,timestamptz,uuid,integer)','execute'),'Worker denied');
select is((select count(*) from patient_weights where pet_id=(select id from fx where k='pet')),1::bigint,'Reads and acknowledgments create no additional weight');
select is((select weight from patient_weights where id=(select id from fx where k='weight')),12.3::numeric,'Native historical weight unchanged');
select * from finish();rollback;
